{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Halofantrine, which shares the same dibutylaminopropanol side chain and a chlorinated aromatic core as the query, has low and erratic oral bioavailability in humans and animals.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "One retrospective analysis estimated halofantrine average bioavailability at approximately 30% in fasted humans, which would be above the 20% threshold, but this is an outlier based on separate non-stereospecific studies.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Terameprocol, a lipophilic polyphenolic compound, has poor oral bioavailability of approximately 2% in patients, supporting that structurally complex lipophilic molecules often have low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Prochlorperazine, a chlorinated tricyclic compound with a basic amine side chain, has absolute oral bioavailability of 12.5 ± 4.3%, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Terbutaline, an amino alcohol drug, has absolute oral bioavailability of 15.7% ± 4.8%, below the 20% threshold, indicating that amino alcohol-containing drugs often have low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is structurally analogous to halofantrine, which has consistently low oral bioavailability (mostly <20%) despite one outlier estimate of ~30%. Other amino alcohol and chlorinated aromatic compounds in the evidence set also show low F. Therefore, the query is predicted to have F < 20% (low).",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "The halofantrine record C08 (~30% F) is an outlier and based on retrospective analysis, creating some uncertainty.",
    "The query's exact tricyclic stilbene-like core is not represented in the evidence set; halofantrine has a phenanthrene core, which may differ in solubility and metabolism."
  ],
